const results = {};
for (const [name, probe] of Object.entries({
  processEnv: () => process.env,
  rootDirectory: () => require('fs').readdirSync('/'),
  bunGlobal: () => globalThis.Bun,
  fetchExample: () => fetch('https://example.com')
})) {
  try {
    const value = probe();
    results[name] = { returned: String(value) };
  } catch (error) {
    results[name] = { error: `${error?.name}: ${error?.message}` };
  }
}
return results;
